#!ibl edition=2
$s = [sense:legal]{query:"민법"}
$chunks = split($s.message,"\"법령일련번호\"")
$hit = filter($chunks,($c)=>contains($c,"\"법령명한글\": \"민법\""))
$id = split(split($hit[0],"\"법령ID\": \"")[1],"\"")[0]
$a = [sense:legal]{id:$id}
$J = get(get(get($a,"법령"),"조문"),"조문단위")
$x = filter($J,($j)=>get($j,"조문여부") == "조문" and (get($j,"조문번호") == "162" or get($j,"조문번호") == "1019" or get($j,"조문번호") == "766"))
return {id:$id,n:len($J),size:len(json($a)),x:$x}
